package com.vandorlabs.neoforge.screen;
import com.google.gson.*;
import com.vandorlabs.screen.ScreenFamily;
import com.vandorlabs.redstone.ChannelList;
import net.minecraft.nbt.*;
/** Exact owned-field comparisons against ordered actual Source selector setters. */
public final class ScreenDisplayEditChecks {
 public static void main(String[] args)throws Exception{JsonObject reference;try(var reader=java.nio.file.Files.newBufferedReader(java.nio.file.Path.of(System.getProperty("screenDisplayEditsReference")))){reference=JsonParser.parseReader(reader).getAsJsonObject();}int cases=0;var catalog=NativeScreenCatalog.INSTANCE;for(var entry:reference.getAsJsonArray("cases")){var row=entry.getAsJsonObject();CompoundTag before=TagParser.parseTag(row.get("before").getAsString()),source=TagParser.parseTag(row.get("after").getAsString());var old=NativeScreenSettings.read(before,catalog);int[] channels=new int[row.getAsJsonArray("channels").size()];for(int i=0;i<channels.length;i++)channels[i]=row.getAsJsonArray("channels").get(i).getAsInt();var edit=new NativeScreenDisplayEdit(row.get("screen").getAsString(),row.get("enabled").getAsBoolean(),row.get("inverted").getAsBoolean(),row.get("playback").getAsInt(),row.get("framed").getAsBoolean(),row.get("speed").getAsInt(),row.get("input").getAsString(),row.get("secondary").getAsString(),row.get("small").getAsBoolean(),row.get("housing").getAsInt(),ChannelList.of(channels));var result=edit.apply(ScreenFamily.fromId(row.get("id").getAsString()),old,catalog);if(result==null)throw new AssertionError("Valid Source edit refused");CompoundTag actual=new CompoundTag();result.write(actual);for(String key:actual.getAllKeys())if(!java.util.Objects.equals(actual.get(key),source.get(key)))throw new AssertionError("Selector differs "+row.get("id")+" field="+key+" actual="+actual.get(key)+" source="+source.get(key));if(edit.apply(ScreenFamily.fromId(row.get("id").getAsString()),result,catalog)!=result)throw new AssertionError("Repeated identical selector edit allocates/replaces settings");cases++;}if(cases!=672||!reference.get("sha256").getAsString().equals("ed3bd3182275cb653059673a645e4304d36e2e8d877164faf8be3508f7ddcb86"))throw new AssertionError("Source selector coverage");System.out.println("Native Screen selector edit PASS actual Source profiles="+cases+" repeated no-op identity retained");}
}
